breach.segment:
// Absolute floor: 32 GiB egressed in the recent slice. Set this to the point where an unexplained
// transfer is worth a human looking at it in your environment; it is the main cost-control knob.
WHERE recent_sent_bytes >= 34359738368
// 6.0 and 18.0 are the two slice widths in hours — keep them in sync with is_recent/timeWindowSize.
// Cast before dividing: the byte counters are longs and `a / b` would be integer division.
| EVAL recent_egress_gib_per_hour   = ROUND(recent_sent_bytes::DOUBLE / 1073741824.0 / 6.0, 2),
       baseline_egress_gib_per_hour = ROUND(baseline_sent_bytes::DOUBLE / 1073741824.0 / 18.0, 2)
// Context, not a condition: a jump in bytes-per-request means object sizes changed, while a flat
// bytes-per-request with far more requests means a read storm. They need different remediations.
| EVAL recent_bytes_per_request   = ROUND(recent_sent_bytes::DOUBLE / recent_requests, 0),
       baseline_bytes_per_request = ROUND(baseline_sent_bytes::DOUBLE / baseline_requests, 0)
// Step-change test on the unrounded hourly rates. A bucket with no baseline egress at all is
// compared against 1 GiB/hour instead, so the ratio stays finite; the volume floor above already
// makes such a bucket significant.
| EVAL egress_growth_factor = ROUND((recent_sent_bytes::DOUBLE / 6.0)
      / CASE(baseline_sent_bytes > 0, baseline_sent_bytes::DOUBLE / 18.0, 1073741824.0), 2)
| WHERE egress_growth_factor >= 3.0
| SORT egress_growth_factor DESC
| LIMIT 50
